import { Injectable } from '@nestjs/common';
import {
    ValidationArguments,
    ValidationOptions,
    registerDecorator,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { CreateDimensionDto, DimensionTier, overageAllowedEnum } from './create-dimension.dto.js';

/**
 * The only non numeric value which is accepted for the `upperBound` of a tier.
 * It may only be used on the last tier of the tier list, and represents an unbounded tier.
 */
export const UNBOUNDED_TIER_UPPER_BOUND = 'inf';

/**
 * The maximum amount of decimal places which any price field accepts.
 */
const MAX_PRICE_DECIMAL_PLACES = 8;

const isNumericString = (value: unknown): boolean => {
    if (typeof value !== 'string') {
        return false;
    }
    if (value.trim() === '') {
        return false;
    }
    return !isNaN(Number(value)) && isFinite(Number(value));
};

const decimalPlaces = (value: string): number => {
    const decimals = value.split('.')[1];
    return decimals ? decimals.length : 0;
};

/**
 * Sorts the tiers of a dimension by the numerical value of their `tierPosition`.
 * `tierPosition` is a numeric string, therefore a plain lexicographic sort would place `"10"` before `"2"`.
 *
 * The input array is never mutated.
 */
export const sortTiers = <T extends { tierPosition?: string }>(tiers: T[]): T[] => {
    return [...tiers].sort((a, b) => Number(a?.tierPosition) - Number(b?.tierPosition));
};

/**
 * Determines the numerical upper bound of a tier. Unbounded tiers (`"inf"`) resolve to `Infinity`.
 */
export const tierUpperBoundToNumber = (upperBound: string): number => {
    if (upperBound === UNBOUNDED_TIER_UPPER_BOUND) {
        return Infinity;
    }
    return Number(upperBound);
};

/**
 * Validates the shape and the internal consistency of the `tiers` field of a dimension.
 *
 * Returns `undefined` when the tiers are valid, otherwise it returns a human readable reason
 * explaining why the tiers are invalid.
 */
export function validateTiers(tiers: unknown, usageIncrement?: string): string | undefined {
    if (tiers === undefined || tiers === null) {
        // Tiers are optional, and `null` is used to remove the tiers from a dimension.
        return undefined;
    }
    if (!Array.isArray(tiers)) {
        return 'tiers must be an array of tier objects';
    }
    if (tiers.length === 0) {
        return 'tiers must contain at least one tier, pass null to remove the tiers of a dimension';
    }

    const seenPositions: number[] = [];
    for (const tier of tiers) {
        if (!tier || typeof tier !== 'object' || Array.isArray(tier)) {
            return 'each tier must be an object containing the fields tierPosition and upperBound';
        }
        const { tierPosition, upperBound, tierName, unitPrice } = tier as DimensionTier;
        if (!isNumericString(tierPosition)) {
            return `tierPosition must be a numeric string, received: ${JSON.stringify(tierPosition)}`;
        }
        if (Number(tierPosition) < 0) {
            return `tierPosition must be greater than or equal to 0, received: ${tierPosition}`;
        }
        if (seenPositions.includes(Number(tierPosition))) {
            return `tierPosition must be unique for each tier, duplicated tierPosition: ${tierPosition}`;
        }
        seenPositions.push(Number(tierPosition));

        if (typeof upperBound !== 'string' || upperBound.trim() === '') {
            return `upperBound must be a numeric string or "${UNBOUNDED_TIER_UPPER_BOUND}", received: ${JSON.stringify(
                upperBound,
            )}`;
        }
        if (upperBound !== UNBOUNDED_TIER_UPPER_BOUND) {
            if (!isNumericString(upperBound)) {
                return `upperBound must be a numeric string or "${UNBOUNDED_TIER_UPPER_BOUND}", received: ${upperBound}`;
            }
            if (Number(upperBound) <= 0) {
                return `upperBound must be greater than 0, received: ${upperBound}`;
            }
        }
        if (tierName !== undefined && tierName !== null) {
            if (typeof tierName !== 'string' || tierName.trim() === '') {
                return `tierName must be a non empty string, received: ${JSON.stringify(tierName)}`;
            }
        }
        if (unitPrice !== undefined && unitPrice !== null) {
            if (!isNumericString(unitPrice)) {
                return `unitPrice must be a numeric string, received: ${JSON.stringify(unitPrice)}`;
            }
            if (Number(unitPrice) < 0) {
                return `unitPrice must be greater than or equal to 0, received: ${unitPrice}`;
            }
            if (decimalPlaces(unitPrice) > MAX_PRICE_DECIMAL_PLACES) {
                return `unitPrice cannot have more than ${MAX_PRICE_DECIMAL_PLACES} digits of precision after the decimal place, received: ${unitPrice}`;
            }
        }
    }

    const sortedTiers = sortTiers(tiers as DimensionTier[]);
    const increment = usageIncrement !== undefined && usageIncrement !== null ? Number(usageIncrement) : undefined;

    let previousUpperBound = 0;
    for (let index = 0; index < sortedTiers.length; index++) {
        const { upperBound, unitPrice, tierPosition } = sortedTiers[index];
        const isLastTier = index === sortedTiers.length - 1;

        if (upperBound === UNBOUNDED_TIER_UPPER_BOUND && !isLastTier) {
            return `only the last tier can have an upperBound of "${UNBOUNDED_TIER_UPPER_BOUND}", tierPosition: ${tierPosition} is not the last tier`;
        }

        const numericUpperBound = tierUpperBoundToNumber(upperBound);
        if (numericUpperBound <= previousUpperBound) {
            return `tier upperBounds must increase without overlap, tierPosition: ${tierPosition} has an upperBound of ${upperBound} which does not exceed the previous upperBound of ${previousUpperBound}`;
        }
        if (
            increment !== undefined &&
            !isNaN(increment) &&
            increment > 0 &&
            numericUpperBound !== Infinity &&
            !Number.isInteger(numericUpperBound / increment)
        ) {
            return `tier upperBounds must align with the usageIncrement of ${usageIncrement}, tierPosition: ${tierPosition} has an upperBound of ${upperBound}`;
        }

        if (index > 0 && (unitPrice === undefined || unitPrice === null)) {
            return `unitPrice is required for every tier after the first tier, tierPosition: ${tierPosition} is missing a unitPrice`;
        }

        previousUpperBound = numericUpperBound;
    }

    return undefined;
}

/**
 * Volume based tiers cannot be combined with entitlements, a flat consumption price, or overage.
 * Returns `undefined` when there is no conflict, otherwise the reason for the conflict.
 */
export function validateTiersAreMutuallyExclusive({
    tiers,
    usageEntitlement,
    consumptionPrice,
    overageAllowed,
}: {
    tiers?: unknown;
    usageEntitlement?: number | 'inf' | null;
    consumptionPrice?: string | null;
    overageAllowed?: overageAllowedEnum | null;
}): string | undefined {
    if (!Array.isArray(tiers) || tiers.length === 0) {
        return undefined;
    }
    if (usageEntitlement !== undefined && usageEntitlement !== null) {
        return 'tiers cannot be set on a dimension which has a usageEntitlement';
    }
    if (consumptionPrice !== undefined && consumptionPrice !== null) {
        return 'tiers cannot be set on a dimension which has a consumptionPrice, the price of each tier is set with unitPrice';
    }
    if (overageAllowed === overageAllowedEnum.true) {
        return 'tiers cannot be set on a dimension which has overageAllowed set to true';
    }
    return undefined;
}

const tiersValidationMessage = (args: ValidationArguments): string | undefined => {
    const object = args?.object as CreateDimensionDto;
    return (
        validateTiers(args?.value, object?.usageIncrement) ??
        validateTiersAreMutuallyExclusive({
            tiers: args?.value,
            usageEntitlement: object?.usageEntitlement,
            consumptionPrice: object?.consumptionPrice,
            overageAllowed: object?.overageAllowed,
        })
    );
};

@ValidatorConstraint({ name: 'ValidateTiers', async: false })
@Injectable()
export class ValidateTiersRule implements ValidatorConstraintInterface {
    validate(tiers: unknown, args: ValidationArguments): boolean {
        return tiersValidationMessage(args) === undefined;
    }

    defaultMessage(args: ValidationArguments): string {
        return `tiers: ${tiersValidationMessage(args)}`;
    }
}

export function ValidateTiers(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidateTiers',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: ValidateTiersRule,
        });
    };
}

