/**
 * @author Enterprise
 *
 * @Class
 * A single volume based pricing tier of a dimension.
 * Tiers allow high volume usage of a dimension to be billed with a different unit price than low volume usage.
 * <br><br>
 * All the numerical fields are represented as strings in order to avoid any loss of precision.
 */
export class DimensionTier {
    /**
     * The position of the tier within the list of tiers of the dimension.
     * Tiers are always evaluated in ascending numerical order of their `tierPosition`.
     * <br><br>
     * Example: `"1"`
     */
    @IsNumberString()
    @IsNotEmpty()
    @ApiProperty({
        name: 'tierPosition',
        type: String,
        example: '1',
        description:
            'The position of the tier in the list of tiers. Tiers are evaluated in ascending numerical order of the tierPosition.',
    })
    public tierPosition: string;

    /**
     * The inclusive upper bound of the tier expressed in the consumption unit of the dimension.
     * The lower bound of a tier is the upper bound of the previous tier.
     * Only the last tier may use the value `"inf"`, which represents an unbounded tier.
     * <br><br>
     * Example: `"1000"`, `"inf"`
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({
        name: 'upperBound',
        type: String,
        example: '1000',
        description:
            'The inclusive upper bound of the tier. A numeric string, or "inf" for the last tier which makes the tier unbounded.',
    })
    public upperBound: string;

    /**
     * An optional friendly name of the tier. When set it is appended to the name of the invoice line item
     * which is generated for the tier.
     * <br><br>
     * Example: `"First 1000 requests"`
     */
    @IsOptional()
    @IsString()
    @IsNotEmpty()
    @ApiProperty({
        name: 'tierName',
        type: String,
        required: false,
        example: 'First 1000 requests',
        description: 'A friendly name for the tier, appended to the name of the invoice line item of the tier.',
    })
    public tierName?: string;

    /**
     * The unit price of the usage which falls within the tier.
     * Required for every tier except for the first tier, where omitting the price defines a free tier.
     * <br><br>
     * Example: `"0.05"`
     */
    @IsOptional()
    @IsNumberString()
    @ValidateDecimalPlace('unitPrice')
    @ApiProperty({
        name: 'unitPrice',
        type: String,
        required: false,
        example: '0.05',
        description:
            'The unit price for the usage falling in this tier. Required for every tier after the first one. Omitting it on the first tier creates a free tier.',
    })
    public unitPrice?: string;
}

export class CreateDimensionDto {

@ShouldSetConsumptionPrice('consumptionPrice')
@ValidateDecimalPlace('consumptionPrice')
public consumptionPrice?: string;

/**
 * An optional list of volume based pricing tiers for the dimension.
 * When tiers are set, the usage of the dimension is allocated across the tiers and each consumed tier
 * is billed with its own unit price, producing one invoice line item per consumed tier.
 * <br><br>
 * Every tier requires the fields `tierPosition` and `upperBound`, and optionally accepts `tierName` and `unitPrice`.
