/**
 * Allocates the total usage of a dimension across the volume based pricing tiers of that dimension.
 *
 * The tiers are always processed in ascending numerical order of their `tierPosition`.
 * The `upperBound` of a tier is inclusive and the lower bound of a tier is the upper bound of the
 * previous tier, therefore the tiers `["1000", "2000"]` allocate the first 1000 units of usage to the
 * first tier and the next 1000 units of usage to the second tier.
 *
 * Only the tiers which have actually been consumed are returned.
 */
public static allocateUsageToTiers({
    totalUsage,
    tiers,
}: {
    totalUsage: number;
    tiers: DimensionTier[];
}): TierUsageAllocation[] {
    const allocations: TierUsageAllocation[] = [];
    if (!Array.isArray(tiers) || tiers.length === 0) {
        return allocations;
    }
    let remainingUsage = Number(totalUsage);
    if (!remainingUsage || isNaN(remainingUsage) || remainingUsage <= 0) {
        return allocations;
    }
    let lowerBound = 0;
    for (const tier of sortTiers(tiers)) {
        const upperBound = tierUpperBoundToNumber(tier?.upperBound);
        const tierCapacity = upperBound - lowerBound;
        if (tierCapacity <= 0) {
            continue;
        }
        const usageInTier = Math.min(remainingUsage, tierCapacity);
        if (usageInTier > 0) {
            allocations.push({ tier, usage: usageInTier, lowerBound, upperBound });
        }
        remainingUsage -= usageInTier;
        lowerBound = upperBound;
        if (remainingUsage <= 0) {
            break;
        }
    }
    if (remainingUsage > 0) {
        // The highest tier is bounded and the customer consumed more than the highest upper bound.
        // The remaining usage is billed with the price of the highest tier so that no usage is lost.
        const highestTierAllocation = allocations[allocations.length - 1];
        if (highestTierAllocation) {
            highestTierAllocation.usage += remainingUsage;
        }
    }
    return allocations;
}

