        const shouldDisplayLineItem = Billing.determineIfLineItemShown({
            Offering: offeringInstance,
            dimension: dimensionMap[dimensionId],
            totalUsage: dimensionTotals[dimensionId] as number,
            unitCost,
            freeDimensionOnInvoice: offeringInstance.settings?.freeDimensionOnInvoice,
        });
        if (shouldDisplayLineItem) {
            const {
                usageIncrement,
                consumptionUnit: { unit, type },
            } = dimensionMap[dimensionId];
            // Handle currency conversion

            const { displayName, total: displayTotal } = InvoiceLineItem.prepareLineItem({
                total: dimensionTotals[dimensionId],
                dimensionType: type,
                dimensionId,
                dimensionName: dimensionMap[dimensionId].dimensionName,
                offeringName: offeringInstance.offeringName,
                usageIncrement: parseInt(usageIncrement),
                dimensionUnit: unit,
                negative,
            });
            lineItems.addLineItem(new InvoiceLineItem(displayName, displayTotal, unitCost));
        }
    });

    return lineItems;
}

/**
 * Converts a price of a dimension, or of a tier of a dimension, into the currency of the invoice.
 * The precision of the configured price is always preserved, prices without any decimals are
 * represented with two decimals.
 */
static convertPriceToInvoiceCurrency(price: string, exchangeRate: number): number {
    const parsedPrice = parseFloat(price);
    if (isNaN(parsedPrice)) {
        // A tier without a unitPrice is a free tier.
        return 0;
    }
    const decimals = Offering.getDecimalsForNumber(parsedPrice);
    return Number((parsedPrice * exchangeRate).toFixed(decimals === 0 ? 2 : decimals));
}

/**
 * Adds one invoice line item for every volume based pricing tier of the dimension which has been consumed.
 * The quantity of each line item is the usage which falls into the tier divided by the usage increment
 * of the dimension, and the unit cost of each line item is the unit price of the tier.
 */
static addTieredLineItemsForDimension({
    dimension,
    totalUsage,
    lineItems,
    exchangeRate,
    negative,
    offeringInstance,
}: {
    dimension: ReadDimensionResponseData;
    totalUsage: number;
    lineItems: InvoiceLineItems;
    exchangeRate: number;
    negative?: boolean;
    offeringInstance: Offering;
}): InvoiceLineItems {
    const {
        dimensionId,
        dimensionName,
        usageIncrement,
        tiers,
        consumptionUnit: { unit, type },
    } = dimension;
    const allocations = Billing.allocateUsageToTiers({ totalUsage, tiers });
    allocations.forEach(({ tier, usage: usageInTier }) => {
        const unitCost = Offering.convertPriceToInvoiceCurrency(tier?.unitPrice, exchangeRate);
        const shouldDisplayLineItem = Billing.determineIfLineItemShown({
            Offering: offeringInstance,
            dimension,
            totalUsage: usageInTier,
            unitCost,
            freeDimensionOnInvoice: offeringInstance.settings?.freeDimensionOnInvoice,
        });
        if (!shouldDisplayLineItem) {
            return;
        }
        const { displayName, total: displayTotal } = InvoiceLineItem.prepareLineItem({
            total: usageInTier,
            dimensionType: type,
            dimensionId,
            dimensionName,
            offeringName: offeringInstance.offeringName,
            usageIncrement: parseInt(usageIncrement),
            dimensionUnit: unit,
            negative,
            tierName: tier?.tierName,
        });
        lineItems.addLineItem(new InvoiceLineItem(displayName, displayTotal, unitCost));
    });
    return lineItems;
}

