            ).toEqual([]);
        });
        test('accepts tiers which are provided out of order', async () => {
            expect(
                await validationErrors({
                    ...baseDimension,
                    tiers: [
                        { tierPosition: '10', upperBound: 'inf', unitPrice: '0.01' },
                        { tierPosition: '2', upperBound: '2000', unitPrice: '0.02' },
                        { tierPosition: '1', upperBound: '1000', unitPrice: '0.03' },
                    ],
                }),
            ).toEqual([]);
        });
        test('non tiered dimensions still require a consumption price', async () => {
            expect(await validationErrors({ ...baseDimension })).toEqual(['consumptionPrice']);
            expect(await validationErrors({ ...baseDimension, consumptionPrice: '0.4' })).toEqual([]);
        });
        test('rejects tiers combined with a consumption price', async () => {
            expect(
                await validationErrors({
                    ...baseDimension,
                    consumptionPrice: '0.4',
                    tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.4' }],
                }),
            ).toContain('tiers');
        });
        test('rejects tiers combined with a usage entitlement', async () => {
            expect(
                await validationErrors({
                    ...baseDimension,
                    usageEntitlement: 100,
                    tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.4' }],
                }),
            ).toContain('tiers');
        });
        test('rejects tiers combined with overage', async () => {
            expect(
                await validationErrors({
                    ...baseDimension,
                    overageAllowed: overageAllowedEnum.true,
                    tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.4' }],
                }),
            ).toContain('tiers');
        });
        test('rejects overlapping or decreasing upper bounds', () => {
            expect(
                validateTiers([
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '2', upperBound: '500', unitPrice: '1' },
                ]),
            ).toBeDefined();
            expect(
                validateTiers([
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '2', upperBound: '1000', unitPrice: '1' },
                ]),
            ).toBeDefined();
        });
        test('rejects an unbounded tier which is not the last tier', () => {
            expect(
                validateTiers([
                    { tierPosition: '1', upperBound: 'inf' },
                    { tierPosition: '2', upperBound: '1000', unitPrice: '1' },
                ]),
            ).toBeDefined();
        });
        test('rejects upper bounds which do not align with the usage increment', () => {
            expect(
                validateTiers([{ tierPosition: '1', upperBound: '150', unitPrice: '1' }], '100'),
            ).toBeDefined();
            expect(validateTiers([{ tierPosition: '1', upperBound: '200', unitPrice: '1' }], '100')).toBeUndefined();
        });
        test('requires a unit price for every tier after the first one', () => {
            expect(
                validateTiers([
                    { tierPosition: '1', upperBound: '100' },
                    { tierPosition: '2', upperBound: 'inf' },
                ]),
            ).toBeDefined();
            expect(
                validateTiers([
                    { tierPosition: '1', upperBound: '100' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '1' },
                ]),
            ).toBeUndefined();
        });
        test('rejects duplicated tier positions and malformed values', () => {
            expect(
                validateTiers([
                    { tierPosition: '1', upperBound: '100' },
                    { tierPosition: '1', upperBound: 'inf', unitPrice: '1' },
                ]),
            ).toBeDefined();
            expect(validateTiers([{ tierPosition: 'first', upperBound: '100' }])).toBeDefined();
            expect(validateTiers([{ tierPosition: '1', upperBound: 'unlimited' }])).toBeDefined();
            expect(validateTiers([{ tierPosition: '1', upperBound: '100', unitPrice: 'free' }])).toBeDefined();
            expect(
                validateTiers([{ tierPosition: '1', upperBound: '100', unitPrice: '0.1234567891' }]),
            ).toBeDefined();
            expect(validateTiers([])).toBeDefined();
        });
        test('tiers are optional and can be removed with null', async () => {
            expect(await validate(plainToInstance(UpdateDimensionDto, { tiers: null }))).toEqual([]);
            expect(validateTiers(undefined)).toBeUndefined();
            expect(validateTiers(null)).toBeUndefined();
        });
        test('sorts the tiers by the numerical value of the tier position', () => {
            expect(
                sortTiers([{ tierPosition: '10' }, { tierPosition: '2' }, { tierPosition: '1' }]).map(
                    ({ tierPosition }) => tierPosition,
                ),
            ).toEqual(['1', '2', '10']);
        });
    });

    describe('persistence', () => {
        const influxServiceMock = () =>
            ({
                getPoint: (measurement: string) => new Point(measurement),
            }) as any;
        const tiers: DimensionTier[] = [
            { tierPosition: '1', upperBound: '1000', tierName: 'Starter' },
            { tierPosition: '2', upperBound: 'inf', unitPrice: '0.05' },
        ];

        test('tiers are stored on the dimension and read back unchanged', () => {
            const service = new DimensionsService(influxServiceMock(), null, null, null);
            const input = service.transformDtoToEntityInput(
                { ...baseDimension, tiers, businessID: 'fakeBusinessID' } as any,
                'fakeDimensionId',
            );
            expect(input.numerical.tiers).toEqual(tiers);

            const point = DimensionEntity.transformer(new DimensionEntity(input), influxServiceMock());
            expect(point.toLineProtocol()).toContain('tiers=');

            const entity = DimensionEntity.dbModelToEntity({
                _value: 'Requests',
                businessID: 'fakeBusinessID',
                dimensionId: 'fakeDimensionId',
                typeofDimension: 'numerical',
                numericalType: 'int',
                dimensionUnit: 'count-based',
                dimensionUnitType: 'count',
                aggregationInterval: 'day',
                aggregationMethod: 'sum',
                priceSegments: JSON.stringify([{ lowerLimit: '0', upperLimit: 'inf' }]),
                sampleType: 'gauge',
                usageIncrement: '1',
                rounding: 'ceiling',
                tiers: JSON.stringify(tiers),
            });
            expect(entity.numerical.tiers).toEqual(tiers);

            const readDto = new CreateDimensionDto(entity);
            expect(readDto.tiers).toEqual(tiers);
            expect(readDto.consumptionPrice).toBeUndefined();
        });

        test('non tiered dimensions are unaffected', () => {
            const service = new DimensionsService(influxServiceMock(), null, null, null);
            const input = service.transformDtoToEntityInput(
                { ...baseDimension, consumptionPrice: '0.4', businessID: 'fakeBusinessID' } as any,
                'fakeDimensionId',
            );
            expect(input.numerical.tiers).toBeUndefined();
            expect(input.numerical.priceSegments).toEqual([{ lowerLimit: '0', upperLimit: 'inf', price: '0.4' }]);
            expect(
                DimensionEntity.transformer(new DimensionEntity(input), influxServiceMock()).toLineProtocol(),
            ).not.toContain('tiers=');
        });
    });

    describe('update', () => {
        let service: DimensionsService;
        let loadedPoints: Point[];
        const existingFlatDimension = {
            dimensionId: 'fakeDimensionId',
            dimensionName: 'Requests',
            consumptionUnit: { unit: 'count-based', type: 'count' },
            usageIncrement: '1',
            rounding: 'ceiling',
            consumptionPrice: '0.4',
            overageAllowed: overageAllowedEnum.false,
        };

        beforeEach(() => {
            loadedPoints = [];
            service = new DimensionsService(
                {
                    getPoint: (measurement: string) => new Point(measurement),
                    loadPoints: async (_bucket, _org, points) => {
                        loadedPoints = points;
                    },
                } as any,
                null,
                null,
                null,
            );
        });

        const mockExistingDimension = (dimension: Record<string, unknown>) =>
            jest
                .spyOn(service, 'findOne')
                .mockImplementation(async () => ({ data: [dimension as any], message: 'Found Dimension' }));

        test('a flat dimension can be converted into a tiered dimension', async () => {
            mockExistingDimension(existingFlatDimension);
            await service.update(
                {
                    dimensionId: 'fakeDimensionId',
                    businessID: 'fakeBusinessID',
                    tiers: [
                        { tierPosition: '1', upperBound: '1000', unitPrice: '0.4' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '0.2' },
                    ],
                } as any,
                'fakeSubject',
            );
            const lineProtocol = loadedPoints[0].toLineProtocol();
            expect(lineProtocol).toContain('tiers=');
            // The flat consumption price of the dimension is removed when the dimension becomes tiered
            expect(lineProtocol).not.toContain('"price"');
        });

        test('tiers are replaced and can be removed with null', async () => {
            mockExistingDimension({
                ...existingFlatDimension,
                consumptionPrice: undefined,
                tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '1' }],
            });
            await service.update(
                {
                    dimensionId: 'fakeDimensionId',
                    businessID: 'fakeBusinessID',
                    tiers: [
                        { tierPosition: '1', upperBound: '10', unitPrice: '2' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '3' },
                    ],
                } as any,
                'fakeSubject',
            );
            expect(loadedPoints[0].toLineProtocol()).toContain('"upperBound":"10"');

            await service.update(
                {
                    dimensionId: 'fakeDimensionId',
                    businessID: 'fakeBusinessID',
                    tiers: null,
                    consumptionPrice: '0.9',
                } as any,
                'fakeSubject',
            );
            const lineProtocol = loadedPoints[0].toLineProtocol();
            expect(lineProtocol).not.toContain('tiers=');
            expect(lineProtocol).toContain('"price":"0.9"');
        });

        test('invalid and conflicting tiers are rejected', async () => {
            mockExistingDimension(existingFlatDimension);
            await expect(
                service.update(
                    {
                        dimensionId: 'fakeDimensionId',
                        businessID: 'fakeBusinessID',
                        tiers: [
                            { tierPosition: '1', upperBound: 'inf' },
                            { tierPosition: '2', upperBound: '10', unitPrice: '1' },
                        ],
                    } as any,
                    'fakeSubject',
                ),
            ).rejects.toThrow();
            await expect(
                service.update(
                    {
                        dimensionId: 'fakeDimensionId',
                        businessID: 'fakeBusinessID',
                        consumptionPrice: '0.4',
                        tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '1' }],
                    } as any,
                    'fakeSubject',
                ),
            ).rejects.toThrow();
        });

        test('invalid tiers are rejected on creation', async () => {
            await expect(
                service.create(
                    {
                        ...baseDimension,
                        usageIncrement: '100',
                        tiers: [{ tierPosition: '1', upperBound: '150', unitPrice: '1' }],
                    } as any,
                    'fakeSubject',
                ),
            ).rejects.toThrow();
        });
    });
});

import { CustomerService } from '../../customer/customer.service.js';
import { paymentChannel } from '../../customer/dto/create-customer.dto.js';
import { ReadCustomerUsageData } from '../../customer/dto/read-customer.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    DimensionTier,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';
import { ReadDimensionResponseData } from '../../dimensions/dto/read-dimension.dto.js';
import { InvoiceLineItem, InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import { InvoicesService } from '../../invoice/invoices.service.js';
import { ValidBillingCycles } from '../../offering/dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../../offering/dto/readOffering.dto.js';
import { SupportedCurrencies } from '../../offering/dto/SupportedCurrencies.js';
import { Offering } from '../../offering/entities/offeringPackage.entity.js';
import { OfferingType } from '../../offering/entities/OfferingType.js';
import { SchedulerService } from '../../scheduler/scheduler.service.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { DatetimeUtils } from '../../utils/datetime.js';
import { Billing } from './billing.entity.js';

jest.mock('../../analytics/analytics.service', () => ({
    AnalyticsService: {
        getExchangeRate: jest.fn(() => 0.91),
    },
}));

const fakeBusinessID = 'fakeBusinessID';
const fakeCustomerID = 'fakeCustomerID';

describe('Tiered dimension billing', () => {
    let invoicesService: InvoicesService;
    let customerService: CustomerService;
    let schedulerService: SchedulerService;

    const tiers: DimensionTier[] = [
        { tierPosition: '1', upperBound: '1000', tierName: 'Free' },
        { tierPosition: '2', upperBound: '2000', unitPrice: '0.05', tierName: 'Growth' },
        { tierPosition: '3', upperBound: 'inf', unitPrice: '0.01', tierName: 'Volume' },
    ];

    const tieredDimension = {
        dimensionId: '123',
        dimensionName: 'Requests',
        aggregationInterval: aggregationInterval.month,
        aggregationMethod: aggregationMethod.sum,
        usageIncrement: '1',
        rounding: roundingEnum.floor,
        consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' as const },
        tiers,
    } as ReadDimensionResponseData;

    beforeAll(() => {
        //eslint-disable-next-line
        //@ts-ignore
        invoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        schedulerService = new SchedulerService();
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    const mockUsage = (value: string) =>
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(
            async () =>
                ({
                    message: 'fake',
                    data: [
                        {
                            dimensionId: '123',
                            usage: [
                                {
                                    startTime: new Date().toISOString(),
                                    endTime: new Date().toISOString(),
                                    value,
                                },
                            ],
                        },
                    ],
                }) as ReadCustomerUsageData,
        );

    const getLineItems = async ({
        dimension = tieredDimension,
        currency = SupportedCurrencies.USD,
        settings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData,
    }: {
        dimension?: ReadDimensionResponseData;
        currency?: SupportedCurrencies;
        settings?: ReadSettingsResponseData;
    } = {}): Promise<InvoiceLineItems> => {
        const offeringConfig = {
            offeringId: '123',
            offeringName: 'foobar',
            offeringType: OfferingType.usageBased,
            currency,
            dimensions: [dimension],
            billingCycle: ValidBillingCycles.monthly,
        } as ReadOfferingResponseData;
        const customer = {
            customerId: fakeCustomerID,
            customerName: 'fakeCustomerName',
            paymentChannel: paymentChannel.manual,
            offering: offeringConfig,
            businessID: fakeBusinessID,
            currency,
            email: 'fakeEmail',
        } as ReadCustomerResponseData;

        return Offering.getLineItemsForUsage({
            customerService,
            customer,
            startDate: DatetimeUtils.fifthDayOfLastMonthAtMidnight(new Date()),
            endDate: new Date(),
            customerId: fakeCustomerID,
            businessID: fakeBusinessID,
            dimensions: [dimension],
            lineItems: new InvoiceLineItems(),
            offeringInstance: Offering.getInstance(
                offeringConfig,
                fakeCustomerID,
                fakeBusinessID,
                invoicesService,
                settings,
                schedulerService,
                customerService,
            ),
        });
    };

    describe('Billing.allocateUsageToTiers', () => {
        test('allocates the usage across the inclusive bounds of the tiers', () => {
            expect(Billing.allocateUsageToTiers({ totalUsage: 2500, tiers }).map(({ usage }) => usage)).toEqual([
                1000, 1000, 500,
            ]);
            expect(Billing.allocateUsageToTiers({ totalUsage: 1000, tiers }).map(({ usage }) => usage)).toEqual([1000]);
            expect(Billing.allocateUsageToTiers({ totalUsage: 1001, tiers }).map(({ usage }) => usage)).toEqual([
                1000, 1,
            ]);
        });
        test('processes the tiers in ascending numerical tier position order', () => {
            const unorderedTiers: DimensionTier[] = [
                { tierPosition: '10', upperBound: 'inf', unitPrice: '0.01' },
                { tierPosition: '2', upperBound: '2000', unitPrice: '0.05' },
                { tierPosition: '1', upperBound: '1000' },
            ];
            expect(
                Billing.allocateUsageToTiers({ totalUsage: 2500, tiers: unorderedTiers }).map(
                    ({ tier, usage }) => `${tier.tierPosition}:${usage}`,
                ),
            ).toEqual(['1:1000', '2:1000', '10:500']);
        });
        test('returns no allocations when there is no usage or no tiers', () => {
            expect(Billing.allocateUsageToTiers({ totalUsage: 0, tiers })).toEqual([]);
            expect(Billing.allocateUsageToTiers({ totalUsage: 100, tiers: [] })).toEqual([]);
            expect(Billing.allocateUsageToTiers({ totalUsage: 100, tiers: undefined })).toEqual([]);
        });
        test('bills usage above the highest bounded tier with the price of the highest tier', () => {
            const boundedTiers: DimensionTier[] = [
                { tierPosition: '1', upperBound: '100' },
                { tierPosition: '2', upperBound: '200', unitPrice: '1' },
            ];
            expect(
                Billing.allocateUsageToTiers({ totalUsage: 500, tiers: boundedTiers }).map(({ usage }) => usage),
            ).toEqual([100, 400]);
        });
    });

    describe('Offering.getLineItemsForUsage', () => {
        test('creates a distinct line item per consumed tier and appends the tier name', async () => {
            mockUsage('2500');
            const lineItems = await getLineItems();
            expect(lineItems.getLineItems()).toEqual([
                expect.objectContaining(new InvoiceLineItem('Requests - foobar - Free', 1000, 0)),
                expect.objectContaining(new InvoiceLineItem('Requests - foobar - Growth', 1000, 0.05)),
                expect.objectContaining(new InvoiceLineItem('Requests - foobar - Volume', 500, 0.01)),
            ]);
        });
        test('only creates line items for the tiers which have been consumed', async () => {
            mockUsage('10');
            const lineItems = await getLineItems();
            expect(lineItems.getLineItems()).toEqual([
                expect.objectContaining(new InvoiceLineItem('Requests - foobar - Free', 10, 0)),
            ]);
        });
        test('uses the normal line item name when the tier has no name', async () => {
            mockUsage('1500');
            const lineItems = await getLineItems({
                dimension: {
                    ...tieredDimension,
                    tiers: [
                        { tierPosition: '1', upperBound: '1000', unitPrice: '0.1' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '0.05' },
                    ],
                } as ReadDimensionResponseData,
            });
            expect(lineItems.getLineItems()).toEqual([
                expect.objectContaining(new InvoiceLineItem('Requests - foobar', 1000, 0.1)),
                expect.objectContaining(new InvoiceLineItem('Requests - foobar', 500, 0.05)),
            ]);
        });
        test('divides the quantity of each tier by the usage increment', async () => {
            mockUsage('3000');
            const lineItems = await getLineItems({
                dimension: {
                    ...tieredDimension,
                    usageIncrement: '1000',
                    tiers: [
                        { tierPosition: '1', upperBound: '1000', unitPrice: '10', tierName: 'First' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '5', tierName: 'Rest' },
                    ],
                } as ReadDimensionResponseData,
            });
            expect(lineItems.getLineItems()).toEqual([
                expect.objectContaining(new InvoiceLineItem('Requests - Thousand - foobar - First', 1, 10)),
                expect.objectContaining(new InvoiceLineItem('Requests - Thousand - foobar - Rest', 2, 5)),
            ]);
        });
        test('preserves the precision of the tier prices and converts the currency', async () => {
            mockUsage('1500');
            const lineItems = await getLineItems({
                currency: SupportedCurrencies.EUR,
                dimension: {
                    ...tieredDimension,
                    tiers: [
                        { tierPosition: '1', upperBound: '1000', unitPrice: '1.23456789' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '1.00' },
                    ],
                } as ReadDimensionResponseData,
            });
            expect(lineItems.getLineItems()).toEqual([
                // 1.12345678 = 0.91 * 1.23456789, the exchange rate is mocked to 0.91
                expect.objectContaining(new InvoiceLineItem('Requests - foobar', 1000, 1.12345678)),
                expect.objectContaining(new InvoiceLineItem('Requests - foobar', 500, 0.91)),
            ]);
        });
        test('hides free tiers when the business hides free dimensions', async () => {
            mockUsage('500');
            const lineItems = await getLineItems({
                settings: { freeDimensionOnInvoice: FreeDimensionOnInvoice.hide } as ReadSettingsResponseData,
            });
            expect(lineItems.getLineItems()).toEqual([]);
        });
        test('non tiered dimensions are billed with the flat consumption price', async () => {
            mockUsage('2500');
            const lineItems = await getLineItems({
                dimension: {
                    ...tieredDimension,
                    tiers: undefined,
                    consumptionPrice: '0.4',
                } as ReadDimensionResponseData,
            });
            expect(lineItems.getLineItems()).toEqual([
                expect.objectContaining(new InvoiceLineItem('Requests - foobar', 2500, 0.4)),
            ]);
        });
    });
});

